<?php namespace Hongda\Theme; get_header(); $term=is_tax()?get_queried_object():null; ?>
<section class="page-intro"><div class="wrap"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a> / <a href="<?php echo esc_url(get_post_type_archive_link('hd_product')); ?>">Equipment</a></div><span class="eyebrow">CHOOSE YOUR MACHINE</span><h1><?php echo $term instanceof \WP_Term?esc_html($term->name):'Compact equipment. Complete choice.'; ?></h1><div class="lead"><?php echo $term instanceof \WP_Term?wp_kses_post(term_description($term)):'Explore excavators, wheel loaders, backhoes and skid steers. Compare machines around your application.'; ?></div></div></section>
<section class="section wrap catalogue"><aside><h2>Equipment families</h2><a href="<?php echo esc_url(get_post_type_archive_link('hd_product')); ?>">All equipment</a><?php foreach(families() as $t): ?><a <?php if($term instanceof \WP_Term && $t->term_id===$term->term_id)echo 'aria-current="page"'; ?> href="<?php echo esc_url(term_url($t)); ?>"><?php echo esc_html($t->name); ?><span><?php echo esc_html($t->count); ?></span></a><?php endforeach; ?><form method="get"><label for="max_weight">Maximum operating weight</label><select name="max_weight" id="max_weight"><option value="">Any weight</option><?php foreach([1,2,3,6,12] as $w): ?><option value="<?php echo esc_attr($w); ?>" <?php selected(isset($_GET['max_weight'])&&is_scalar($_GET['max_weight'])?(string)$_GET['max_weight']:'',(string)$w); ?>>Up to <?php echo esc_html($w); ?> t</option><?php endforeach; ?></select><button class="button" type="submit">Apply filter</button></form></aside><div><div class="result-count"><?php global $wp_query; echo esc_html($wp_query->found_posts); ?> machines</div><div class="machine-grid"><?php while(have_posts()):the_post();card();endwhile; ?></div><?php if(!have_posts() && !$wp_query->found_posts): ?><p>No machines match this selection. Choose another weight or equipment family.</p><?php endif; ?><div class="pagination"><?php the_posts_pagination(); ?></div></div></section><?php cta();get_footer(); ?>
